/* ── Aplica estilo de fundo conforme tema ── */
function getFundoStyle(temaId) {
  switch(temaId) {
    case "bege-watermark":    return { background:"#f5f0e8" };
    case "bege-premium":      return { background:"#f7f3ec" };
    case "cinza-suave":       return { background:"linear-gradient(145deg,#eef1f8,#f0f4f9,#e8ecf4)" };
    case "micro-grade":       return { background:"#f4f6f9",
                                       backgroundImage:"linear-gradient(rgba(123,30,46,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(123,30,46,.04) 1px,transparent 1px)",
                                       backgroundSize:"28px 28px" };
    case "radial-elegante":   return { background:"radial-gradient(ellipse at 15% 20%,rgba(123,30,46,.06),transparent 50%),radial-gradient(ellipse at 85% 80%,rgba(0,56,117,.04),transparent 50%),linear-gradient(135deg,#f0f4f9,#f4f6f9)" };
    case "dark-premium":      return { background:"linear-gradient(135deg,#0f1520,#141c2e,#0d1117)" };
    case "branco-puro":       return { background:"#ffffff" };
    case "azul-institucional":return { background:"linear-gradient(145deg,#e8f0fb,#eef4fd,#e4eef8)" };
    default:                  return { background:"#f5f0e8" };
  }
}

/* ── Componente de marca d'água ── */
function MarcaDagua({ temaId }) {
  const watermarkTemas = ["bege-watermark","bege-premium","dark-premium"];
  if (!watermarkTemas.includes(temaId)) return null;
  const isDark = temaId==="dark-premium";
  const cor = isDark ? "rgba(200,151,58,.04)" : "rgba(123,30,46,.065)";
  const rows = Array(10).fill(null);
  return (
    <div className="no-print" style={{ position:"fixed", inset:0, overflow:"hidden",
                  pointerEvents:"none", zIndex:0,
                  transform:"rotate(-25deg)",
                  transformOrigin:"center center" }}>
      {rows.map((_,i)=>(
        <div key={i} style={{ whiteSpace:"nowrap", padding:"18px 0",
                              display:"flex", gap:"40px" }}>
          {Array(8).fill(null).map((_,j)=>(
            <span key={j} style={{ fontSize:12, fontWeight:800,
                                   color:cor, letterSpacing:".28em",
                                   fontFamily:"'Plus Jakarta Sans',sans-serif",
                                   textTransform:"uppercase", userSelect:"none" }}>
              MPRJ-CI² &nbsp; NAPPRA
            </span>
          ))}
        </div>
      ))}
    </div>
  );
}

