              const f=e.target.files[0]; if(!f) return;
              if(f.size>2097152){alert("Imagem muito grande. Máximo 2MB."); return;}
              const r=new FileReader(); r.onload=ev=>setF(fk,ev.target.result); r.readAsDataURL(f);
